package __PKG__;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Stream;

/**
 * Folders, files and simple settings files ("key: value") inside the data folder
 * of the plugin / mod. Generated by Minecraft Builder.
 */
public final class DataFiles {
    private static Path base;
    /** Lines of the settings files that were read already. */
    private static final Map<String, List<String>> CONFIGS = new ConcurrentHashMap<>();

    private DataFiles() {}

    public static synchronized void init(Path dir) {
        base = dir;
        CONFIGS.clear();
        try {
            Files.createDirectories(dir);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** Path inside the data folder. Leaving the folder ("..") is not possible. */
    static Path resolve(String rel) {
        String r = rel == null ? "" : rel.trim().replace('\\', '/');
        while (r.startsWith("/")) r = r.substring(1);
        Path p = base.resolve(r).normalize();
        return p.startsWith(base.normalize()) ? p : base;
    }

    public static synchronized boolean mkdir(String rel) {
        try {
            Files.createDirectories(resolve(rel));
            return true;
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }

    public static synchronized boolean exists(String rel) {
        return base != null && Files.exists(resolve(rel));
    }

    public static synchronized void write(String rel, String text) {
        try {
            Path p = resolve(rel);
            if (p.getParent() != null) Files.createDirectories(p.getParent());
            Files.writeString(p, text == null ? "" : text, StandardCharsets.UTF_8);
            CONFIGS.remove(rel);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static synchronized void append(String rel, String line) {
        try {
            Path p = resolve(rel);
            if (p.getParent() != null) Files.createDirectories(p.getParent());
            Files.writeString(p, (line == null ? "" : line) + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            CONFIGS.remove(rel);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static synchronized String read(String rel) {
        try {
            Path p = resolve(rel);
            return Files.isRegularFile(p) ? Files.readString(p, StandardCharsets.UTF_8) : "";
        } catch (IOException e) {
            e.printStackTrace();
            return "";
        }
    }

    public static synchronized boolean delete(String rel) {
        try {
            Path p = resolve(rel);
            if (p.equals(base)) return false;
            CONFIGS.remove(rel);
            if (Files.isDirectory(p)) {
                try (Stream<Path> s = Files.list(p)) {
                    if (s.findAny().isPresent()) return false;
                }
            }
            return Files.deleteIfExists(p);
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }

    /** Names of the files in a folder, separated by commas. */
    public static synchronized String list(String rel) {
        Path p = resolve(rel);
        if (!Files.isDirectory(p)) return "";
        List<String> names = new ArrayList<>();
        try (Stream<Path> s = Files.list(p)) {
            s.forEach(f -> names.add(f.getFileName().toString()));
        } catch (IOException e) {
            e.printStackTrace();
        }
        java.util.Collections.sort(names);
        return String.join(",", names);
    }

    // ----- settings files ---------------------------------------------------------

    private static List<String> lines(String file) {
        return CONFIGS.computeIfAbsent(file, f -> {
            try {
                Path p = resolve(f);
                if (Files.isRegularFile(p)) return new ArrayList<>(Files.readAllLines(p, StandardCharsets.UTF_8));
            } catch (IOException e) {
                e.printStackTrace();
            }
            return new ArrayList<>();
        });
    }

    private static int find(List<String> lines, String key) {
        for (int i = 0; i < lines.size(); i++) {
            String l = lines.get(i).trim();
            if (l.startsWith("#")) continue;
            int c = l.indexOf(':');
            if (c > 0 && l.substring(0, c).trim().equals(key)) return i;
        }
        return -1;
    }

    private static String unquote(String v) {
        v = v.trim();
        if (v.length() >= 2 && ((v.startsWith("\"") && v.endsWith("\"")) || (v.startsWith("'") && v.endsWith("'")))) {
            return v.substring(1, v.length() - 1).replace("\\\"", "\"").replace("\\\\", "\\");
        }
        return v;
    }

    private static String quote(String v) {
        if (v == null) v = "";
        boolean plain = !v.isEmpty() && v.equals(v.trim()) && v.matches("[A-Za-z0-9_ .,/+-]*");
        return plain ? v : "\"" + v.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }

    private static void store(String file, List<String> lines) {
        try {
            Path p = resolve(file);
            if (p.getParent() != null) Files.createDirectories(p.getParent());
            Files.write(p, lines, StandardCharsets.UTF_8);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static synchronized String cfgText(String file, String key, String def) {
        List<String> lines = lines(file);
        int i = find(lines, key);
        if (i < 0) return def == null ? "" : def;
        String l = lines.get(i);
        return unquote(l.substring(l.indexOf(':') + 1));
    }

    public static synchronized double cfgNum(String file, String key, double def) {
        String v = cfgText(file, key, null);
        try {
            return v == null || v.isEmpty() ? def : Double.parseDouble(v.replace(',', '.'));
        } catch (NumberFormatException e) {
            return def;
        }
    }

    public static synchronized boolean cfgBool(String file, String key, boolean def) {
        String v = cfgText(file, key, "").toLowerCase(java.util.Locale.ROOT);
        if (v.isEmpty()) return def;
        return v.equals("true") || v.equals("yes") || v.equals("ja") || v.equals("on") || v.equals("1");
    }

    public static synchronized void cfgSet(String file, String key, String value) {
        List<String> lines = lines(file);
        int i = find(lines, key);
        String line = key + ": " + quote(value);
        if (i < 0) lines.add(line); else lines.set(i, line);
        store(file, lines);
    }

    /** Adds the setting with a comment if it does not exist yet. */
    public static synchronized void cfgDefault(String file, String key, String value, String comment) {
        List<String> lines = lines(file);
        if (find(lines, key) >= 0) return;
        if (comment != null && !comment.isBlank()) {
            if (!lines.isEmpty()) lines.add("");
            for (String c : comment.split("\n")) lines.add("# " + c);
        }
        lines.add(key + ": " + quote(value));
        store(file, lines);
    }

    public static synchronized void cfgReload(String file) {
        if (file == null || file.isBlank()) CONFIGS.clear(); else CONFIGS.remove(file);
    }
}
